<script setup lang="ts">
import { NInput, NButton } from 'naive-ui'; import { useI18n } from 'vue-i18n'; import { useDraft } from '../composables/useDraft'; import { useSimulatedTask } from '../composables/useSimulatedTask'; import TaskFeedback from './TaskFeedback.vue'; import { workspace } from '../demo/workspace'; const { t } = useI18n()
