</script><template><section class="panel"><h2>{{ t('common.draftLab') }}</h2><p>{{ t('common.draftHint') }}</p><label for="draft-name">{{ t('common.draftName') }}</label><NInput id="draft-name" v-model:value="value.name" :maxlength="120" /><div class="actions"><NButton :disabled="!dirty" @click="save">{{ t('common.saveDraft') }}</NButton><NButton :disabled="!dirty" @click="discard">{{ t('common.discard') }}</NButton><NButton :disabled="state === 'running'" @click="run(workspace.scenario === 'error' ? 'error' : 'success')">{{ t('common.simulate') }}</NButton></div><TaskFeedback :state="state" @cancel="cancel" /></section></template>
